import{_ as t,o,c as r,a3 as a}from"./chunks/framework.C4dN0wKy.js";const p=JSON.parse('{"title":"Troubleshoot the Hyperliquid JavaScript SDK","description":"Resolve installation and import errors, missing account data, WebSocket subscription problems, request timeouts and rejected Hyperliquid orders.","frontmatter":{"title":"Troubleshoot the Hyperliquid JavaScript SDK","description":"Resolve installation and import errors, missing account data, WebSocket subscription problems, request timeouts and rejected Hyperliquid orders."},"headers":[],"relativePath":"guides/troubleshooting.md","filePath":"guides/troubleshooting.md"}'),s={name:"guides/troubleshooting.md"};function i(n,e,d,c,u,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with the symptom below. Check the network and the client you are using before changing credentials or retrying a request.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Start here</th></tr></thead><tbody><tr><td>Package cannot be found or imported</td><td><a href="#installation-and-imports">Installation and imports</a></td></tr><tr><td>A price, order book or account result is missing</td><td><a href="#missing-or-unexpected-data">Missing or unexpected data</a></td></tr><tr><td>An account or signer error appears</td><td><a href="#account-addresses-and-signing">Account addresses and signing</a></td></tr><tr><td>A subscription connects but no updates arrive</td><td><a href="#websocket-subscriptions">WebSocket subscriptions</a></td></tr><tr><td>A request times out or returns an error</td><td><a href="#request-failures">Request failures</a></td></tr><tr><td>An order request resolves but an order is rejected</td><td><a href="#rejected-orders">Rejected orders</a></td></tr></tbody></table><h2 id="installation-and-imports" tabindex="-1">Installation and imports <a class="header-anchor" href="#installation-and-imports" aria-label="Permalink to &quot;Installation and imports&quot;">​</a></h2><p>For <code>ERR_MODULE_NOT_FOUND</code> or <code>Cannot find module</code>, run <code>npm ls @siebly/hyperliquid-api</code> in the project that runs your script. Install the package there if it is missing. Check <code>node --version</code> against the requirement shown in the <a href="/docs/hyperliquid/getting-started.html#installation">Quickstart</a>.</p><p>For <code>Cannot use import statement outside a module</code>, save the Quickstart example as <code>prices.mjs</code>, or configure your project to use ES modules with <code>&quot;type&quot;: &quot;module&quot;</code> in <code>package.json</code>. A <code>.cjs</code> file uses CommonJS <code>require()</code> instead. See <a href="/docs/hyperliquid/getting-started.html#module-formats">module formats</a>.</p><p>The Quickstart example uses JavaScript-compatible syntax. Other TypeScript examples may need your project&#39;s TypeScript compiler or runner; renaming a file does not remove type annotations.</p><h2 id="missing-or-unexpected-data" tabindex="-1">Missing or unexpected data <a class="header-anchor" href="#missing-or-unexpected-data" aria-label="Permalink to &quot;Missing or unexpected data&quot;">​</a></h2><h3 id="a-mid-price-is-missing" tabindex="-1">A mid price is missing <a class="header-anchor" href="#a-mid-price-is-missing" aria-label="Permalink to &quot;A mid price is missing&quot;">​</a></h3><p><code>getAllMids()</code> returns a map keyed by native coin name. Check the returned keys and the selected network. Do not assume every market uses the symbol shown in a user interface. The <a href="/docs/hyperliquid/guides/market-data.html#asset-names">asset-name guide</a> explains native perpetual, Spot and HIP-3 names.</p><h3 id="an-order-book-is-null-or-a-side-is-empty" tabindex="-1">An order book is null or a side is empty <a class="header-anchor" href="#an-order-book-is-null-or-a-side-is-empty" aria-label="Permalink to &quot;An order book is null or a side is empty&quot;">​</a></h3><p><code>getOrderBook()</code> can return <code>null</code>. Check for it before reading <code>levels</code>; either bids or asks can also be empty. Verify the market identifier and network. The <a href="/docs/hyperliquid/guides/market-data.html#l2-order-book">order-book example</a> handles these cases explicitly.</p><h3 id="account-positions-are-empty" tabindex="-1">Account positions are empty <a class="header-anchor" href="#account-positions-are-empty" aria-label="Permalink to &quot;Account positions are empty&quot;">​</a></h3><p>An empty <code>assetPositions</code> array can be a valid result. Check that <code>accountAddress</code> is the account being queried, rather than an API wallet&#39;s signing address, and confirm Mainnet versus Testnet. Use <a href="/docs/hyperliquid/guides/authentication.html#read-account-state">account queries</a> to inspect the intended account.</p><h2 id="account-addresses-and-signing" tabindex="-1">Account addresses and signing <a class="header-anchor" href="#account-addresses-and-signing" aria-label="Permalink to &quot;Account addresses and signing&quot;">​</a></h2><p>If an account query asks you to provide <code>user</code>, <code>accountAddress</code> or <code>vaultAddress</code>, the SDK could not resolve an account from the request or client configuration. Public account queries need an address, not a private key. Set <code>accountAddress</code>, or pass <code>user</code> to that request.</p><p>If the SDK reports that the signer is not a Hyperliquid account on this network, check the selected network and set <code>accountAddress</code> to the account managed by the API wallet. That setting selects the account; it does not authorize the signer. Review <a href="/docs/hyperliquid/guides/authentication.html#api-wallets-and-vaults">API wallets and vaults</a>.</p><p>For a rejected signed action, verify the signer is authorized for the account and action. Check that <code>testnet</code> matches any custom endpoint. See <a href="/docs/hyperliquid/guides/authentication.html">Authentication</a> and <a href="/docs/hyperliquid/guides/configuration.html#networks">network configuration</a>.</p><h2 id="websocket-subscriptions" tabindex="-1">WebSocket subscriptions <a class="header-anchor" href="#websocket-subscriptions" aria-label="Permalink to &quot;WebSocket subscriptions&quot;">​</a></h2><p>A resolved <code>subscribe()</code> promise confirms that the subscription was sent locally. Check <code>response</code> for the server acknowledgement and <code>exception</code> for a rejection or connection failure.</p><p>Register listeners before subscribing. Read subscription data from <code>message</code> and narrow it using <code>channel</code>. Use a native coin name for channels that take <code>coin</code>; resolve an alias with <code>nameToCoin()</code> first when necessary.</p><p>If the connection is repeatedly lost, check connectivity and proxy settings, then review connection and heartbeat options in <a href="/docs/hyperliquid/api/interfaces/WebsocketClientOptions.html"><code>WebsocketClientOptions</code></a>. A larger timeout does not correct an invalid subscription. See the <a href="/docs/hyperliquid/guides/websockets.html">complete subscription example</a>.</p><h2 id="request-failures" tabindex="-1">Request failures <a class="header-anchor" href="#request-failures" aria-label="Permalink to &quot;Request failures&quot;">​</a></h2><h3 id="http-errors-and-timeouts" tabindex="-1">HTTP errors and timeouts <a class="header-anchor" href="#http-errors-and-timeouts" aria-label="Permalink to &quot;HTTP errors and timeouts&quot;">​</a></h3><p>Inspect <code>HyperliquidApiError.message</code>, <code>status</code> and <code>code</code>. <code>status</code> can be absent if no HTTP response arrived. An API-level rejection can also arrive with HTTP status <code>200</code>, so inspect the SDK error rather than the status alone.</p><p>HTTP requests are not automatically retried. Check connectivity and the endpoint for transport failures, reduce request volume when rate limited, and correct input for validation failures. Use <a href="/docs/hyperliquid/guides/errors.html">Error handling</a> for the error model and <a href="/docs/hyperliquid/guides/production.html#timeouts-and-retries">Production usage</a> for retry decisions.</p><h3 id="websocket-request-timeouts" tabindex="-1">WebSocket request timeouts <a class="header-anchor" href="#websocket-request-timeouts" aria-label="Permalink to &quot;WebSocket request timeouts&quot;">​</a></h3><p><code>connectionTimeout</code> controls opening a socket. <code>requestTimeoutMs</code> covers an individual request, including connection setup. Use <a href="/docs/hyperliquid/guides/configuration.html#websocket-connections">Configuration</a> to adjust them for your environment.</p><p>After a timeout or disconnect during a signed action, the outcome may be unknown. <a href="/docs/hyperliquid/guides/production.html#check-an-order-after-a-timeout">Check the order state</a> before deciding whether to resubmit it.</p><h2 id="rejected-orders" tabindex="-1">Rejected orders <a class="header-anchor" href="#rejected-orders" aria-label="Permalink to &quot;Rejected orders&quot;">​</a></h2><p>A successful <code>submitOrder()</code> request can contain an <code>error</code> entry for one or more orders. Inspect each entry in <code>response.data.statuses</code>; do not infer acceptance from the fulfilled promise alone. See <a href="/docs/hyperliquid/guides/errors.html#order-results">Order results</a> for the response variants.</p><h2 id="collect-a-reproducible-report" tabindex="-1">Collect a reproducible report <a class="header-anchor" href="#collect-a-reproducible-report" aria-label="Permalink to &quot;Collect a reproducible report&quot;">​</a></h2><p>Include the SDK version (<code>npm ls @siebly/hyperliquid-api</code>), Node version, network, method, minimal example and relevant error fields. For streams, include the channel and connection events around the failure. Remove private keys, signed payloads and other sensitive values before sharing a report.</p><p>Check the <a href="https://github.com/sieblyio/hyperliquid-api/issues" target="_blank" rel="noreferrer">SDK issue tracker</a> for existing reports and fixes.</p>',34)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
